1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_irq.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Beken BK7258 (T5-AI, Cortex-M33) NVIC interrupt support for NuttX N2.
7	 *
8	 * Standard Cortex-M NVIC glue, modelled on nuttx/arch/arm/src/mps/mps_irq.c.
9	 * Provides up_irqinitialize() / up_enable_irq() / up_disable_irq() /
10	 * up_prioritize_irq() / arm_ack_irq() that the common armv8-m dispatch
11	 * code (arm_doirq.c, arm_exception.S) expects.  The BK7258 exposes 48
12	 * external IRQs (NR_IRQS=48 -> vector slots [16..63]); the chip-provided
13	 * vector table (bk7258_vectors.c) routes SysTick + all external IRQs to
14	 * exception_direct and the system exceptions to exception_common, so once
15	 * up_irqinitialize() runs, irq_attach()/irq_dispatch() work normally.
16	 *
17	 * System-exception IRQ numbers use the canonical arm_m names from nvic.h
18	 * (NVIC_IRQ_HARDFAULT, NVIC_IRQ_SVCALL, NVIC_IRQ_PENDSV, ...) which equal
19	 * the BK7258_IRQ_* values in chip/include/irq.h.
20	 ****************************************************************************/
21	
22	/****************************************************************************
23	 * Included Files
24	 ****************************************************************************/
25	
26	#include <nuttx/config.h>
27	
28	#include <stdint.h>
29	#include <assert.h>
30	#include <debug.h>
31	
32	#include <nuttx/arch.h>
33	#include <arch/irq.h>
34	
35	#include "ram_vectors.h"
36	#include "arm_internal.h"
37	#include "nvic.h"
38	
39	/****************************************************************************
40	 * Pre-processor Definitions
41	 ****************************************************************************/
42	
43	/* NVIC enable/clear register bank stride. */
44	
45	#define NVIC_ENA_OFFSET         (0)
46	#define NVIC_CLRENA_OFFSET      (NVIC_IRQ0_31_CLEAR - NVIC_IRQ0_31_ENABLE)
47	
48	/* Default priority packed four-per-register (one stroke for all 4 slots). */
49	
50	#define DEFPRIORITY32           (NVIC_SYSH_PRIORITY_DEFAULT << 24 | \
51	                                 NVIC_SYSH_PRIORITY_DEFAULT << 16 | \
52	                                 NVIC_SYSH_PRIORITY_DEFAULT << 8  | \
53	                                 NVIC_SYSH_PRIORITY_DEFAULT)
54	
55	/****************************************************************************
56	 * Private Functions
57	 ****************************************************************************/
58	
59	/****************************************************************************
60	 * Name: bk7258_prioritize_syscall
61	 *
62	 * Description:
63	 *   Set the priority of the SVCall exception (system handler 11).  Needed
64	 *   internally even when CONFIG_ARCH_IRQPRIO is off.
65	 *
66	 ****************************************************************************/
67	
68	static inline void bk7258_prioritize_syscall(int priority)
69	{
70	  uint32_t regval;
71	
72	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
73	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
74	  regval |= (priority << NVIC_SYSH_PRIORITY_PR11_SHIFT);
75	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
76	}
77	
78	/****************************************************************************
79	 * Public Functions
80	 ****************************************************************************/
81	
82	/****************************************************************************
83	 * Name: up_prioritize_irq
84	 *
85	 * Description:
86	 *   Set the priority of an IRQ.
87	 *
88	 ****************************************************************************/
89	
90	int up_prioritize_irq(int irq, int priority)
91	{
92	  uint32_t regaddr;
93	  uint32_t regval;
94	  int shift;
95	
96	  DEBUGASSERT(irq >= 0 && irq < NR_IRQS &&
97	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
98	
99	  if (irq < 16)
100	    {
101	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of the priority registers
102	       * (0-3 are invalid as raw indices; they are remapped internally).
103	       */
104	
105	      regaddr = NVIC_SYSH_PRIORITY(irq);
106	      irq    -= 4;
107	    }
108	  else
109	    {
110	      /* NVIC_IRQ_PRIORITY() maps {0..} to the external priority registers. */
111	
112	      irq    -= 16;
113	      regaddr = NVIC_IRQ_PRIORITY(irq);
114	    }
115	
116	  regval  = getreg32(regaddr);
117	  shift   = ((irq & 3) << 3);
118	  regval &= ~(0xff << shift);
119	  regval |= (priority << shift);
120	  putreg32(regval, regaddr);
121	
122	  return OK;
123	}
