125	/****************************************************************************
126	 * Name: up_irqinitialize
127	 *
128	 * Description:
129	 *   Bring the NVIC up to a known, ready state.  Called from up_initialize().
130	 *
131	 ****************************************************************************/
132	
133	void up_irqinitialize(void)
134	{
135	  uint32_t regaddr;
136	  int num_priority_registers;
137	  int i;
138	
139	  /* Disable all external interrupts. */
140	
141	  for (i = 0; i < NR_IRQS - BK7258_IRQ_FIRST; i += 32)
142	    {
143	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
144	    }
145	
146	  /* Point VTOR at our flash-resident vector table (also set in __start;
147	   * redundant here but deterministic).
148	   */
149	
150	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
151	
152	#ifdef CONFIG_ARCH_RAMVECTORS
153	  arm_ramvec_initialize();
154	#endif
155	
156	  /* Default-prioritise the system exceptions. */
157	
158	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
159	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
160	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
161	
162	  /* The NVIC ICTR register (bits 0-4) holds (number of IRQ lines / 32) - 1,
163	   * which also tells us how many priority registers to default-fill.
164	   */
165	
166	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
167	
168	  regaddr = NVIC_IRQ0_3_PRIORITY;
169	  while (num_priority_registers--)
170	    {
171	      putreg32(DEFPRIORITY32, regaddr);
172	      regaddr += 4;
173	    }
174	
175	  /* Attach the SVCall and HardFault handlers used by the scheduler. */
176	
177	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
178	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
179	
180	  /* PendSV runs at the lowest priority so it never preempts device IRQs. */
181	
182	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
183	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
184	
185	  /* Enable the MemManage fault if the MPU is in use. */
186	
187	#ifdef CONFIG_ARM_MPU
188	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
189	  up_enable_irq(NVIC_IRQ_MEMFAULT);
190	#endif
191	
192	#ifndef CONFIG_SUPPRESS_INTERRUPTS
193	
194	  /* Colour the interrupt stack (writes a sentinel pattern) and unmask IRQs. */
195	
196	  arm_color_intstack();
197	  up_irq_enable();
198	#endif
199	}
