1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/scripts/ld.script
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Linker script for the Beken BK7258 (T5-AI, Cortex-M33) Stage N1 image.
7	 *
8	 * Memory map (reverse-engineered on board; the app partition size follows
9	 * the armino SDK partition table for BK7258):
10	 *
11	 *   FLASH : 0x02010000 .. 0x020FFFFF  (1 MiB logical/XIP window)
12	 *           The on-flash primary_cp_app partition is 1360 KiB (see the
13	 *           armino BK7258 partition CSVs), so a 1 MiB link window sits
14	 *           comfortably inside it.  (Stage N1 used a 64 KiB placeholder
15	 *           because the N1 image was tiny; the full NuttX kernel + NSH is
16	 *           ~70 KiB and would not fit in 64 KiB.)  The Tier-1 bootloader
17	 *           jumps the app Reset entry here after validating the BK7236
18	 *           magic.
19	 *   RAM   : 0x28000000 .. 0x2809FFFF  (640 KiB SRAM)
20	 *   MSP   : 0x2809FFFC  (top of usable SRAM, also stored in vector slot 0)
21	 *
22	 * The .vectors section (66 entries, 0x108 bytes from bk7258_vectors.c) is
23	 * KEEP-pinned first so that:
24	 *   - file offset 0x000 == slot [0] == initial MSP (0x2809FFFC)
25	 *   - file offset 0x004 == slot [1] == __start (Thumb entry)
26	 *   - file offset 0x100 == slot [64] == app magic "BK72"
27	 *   - file offset 0x104 == slot [65] == app magic "36\0\0"
28	 ****************************************************************************/
29	
30	/* The linker script is preprocessed to .tmp before being passed to ld;
31	 * include the build config so CONFIG_ARCH_INTERRUPTSTACK (used in
32	 * .irq_stack below) and any other CONFIG_* values are substituted.
33	 */
34	
35	#include <nuttx/config.h>
36	
37	OUTPUT_ARCH("arm")
38	EXTERN(_vectors)
39	ENTRY(__start)
40	
41	MEMORY
42	{
43	    FLASH (rx)  : ORIGIN = 0x02010000, LENGTH = 0x100000
44	    RAM   (rwx) : ORIGIN = 0x28000000, LENGTH = 0xA0000
45	}
46	
47	/* Initial stack pointer (top of SRAM).  Also stored in vector slot 0. */
48	
49	_estack = 0x2809fffc;
50	
51	SECTIONS
52	{
53	    /* Vector table FIRST, pinned at 0x02010000.  KEEP() prevents the
54	     * linker from GC'ing it; . = ORIGIN(FLASH) pins the address.
55	     */
56	    . = ORIGIN(FLASH);
57	    .vectors : ALIGN(4)
58	    {
59	        KEEP(*(.vectors))
60	        . = ALIGN(4);
61	    } > FLASH
62	
63	    /* Code + read-only data (XIP-readable in flash). */
64	    .text : ALIGN(4)
65	    {
66	        _stext = ABSOLUTE(.);
67	        *(.text .text.*)
68	        *(.fixup)
69	        *(.gnu.warning)
70	        *(.rodata .rodata.*)
71	        *(.gnu.linkonce.t.*)
72	        *(.glue_7)
73	        *(.glue_7t)
74	        *(.gcc_except_table)
75	        *(.gnu.linkonce.r.*)
76	        . = ALIGN(4);
77	        _etext = ABSOLUTE(.);
78	    } > FLASH
79	
80	    /* Constructors / destructors (NuttX init_section convention). */
81	    .init_section : ALIGN(4)
82	    {
83	        _sinit = ABSOLUTE(.);
84	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
85	        KEEP(*(.init_array EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o) .ctors))
86	        _einit = ABSOLUTE(.);
87	    } > FLASH
88	
89	    /* ARM exception unwinding tables -- keep them out of the way. */
90	    .ARM.extab : ALIGN(4)
91	    {
92	        *(.ARM.extab*)
93	    } > FLASH
94	
95	    .ARM.exidx : ALIGN(4)
96	    {
97	        __exidx_start = ABSOLUTE(.);
98	        *(.ARM.exidx*)
99	        __exidx_end = ABSOLUTE(.);
100	    } > FLASH
101	
102	    /* Thread-local storage (NuttX ARM convention). */
103	    .tdata : ALIGN(4)
104	    {
105	        _stdata = ABSOLUTE(.);
106	        *(.tdata .tdata.* .gnu.linkonce.td.*);
107	        _etdata = ABSOLUTE(.);
108	    } > FLASH
109	
110	    .tbss : ALIGN(4)
111	    {
112	        _stbss = ABSOLUTE(.);
113	        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
114	        _etbss = ABSOLUTE(.);
115	    } > FLASH
116	
117	    /* Load address of .data (LMA right after the last flash-resident
118	     * section).  Reset code copies from _eronly to _sdata.._edata.
119	     */
120	    _eronly = LOADADDR(.data);
121	
122	    /* Interrupt stack in RAM (NuttX arm_getintstack.c references
123	     * g_intstackalloc / g_intstacktop).  Placed at the very start of RAM
124	     * so it has a fixed, predictable location.
125	     */
126	    .irq_stack : ALIGN(4)
127	    {
128	        g_intstackalloc = ABSOLUTE(.);
129	        . += CONFIG_ARCH_INTERRUPTSTACK;
130	        g_intstacktop = ABSOLUTE(.);
131	    } > RAM
132	
133	    .ram_vectors (NOLOAD) : ALIGN(512)
134	    {
135	        _sram_vectors = ABSOLUTE(.);
136	        KEEP(*(.ram_vectors))
137	        . = ALIGN(4);
138	        _eram_vectors = ABSOLUTE(.);
139	    } > RAM
140	
141	    ASSERT((_sram_vectors & 0x1ff) == 0,
142	           "ERROR: .ram_vectors must be 512-byte aligned")
143	
144	    /* Initialized data: VMA in RAM, LMA in FLASH right after .tbss/.ARM. */
145	    .data : ALIGN(4)
146	    {
147	        _sdata = ABSOLUTE(.);
148	        *(.data .data.*)
149	        *(.gnu.linkonce.d.*)
150	        CONSTRUCTORS
151	        . = ALIGN(4);
152	        _edata = ABSOLUTE(.);
153	    } > RAM AT > FLASH
154	
155	    /* Zero-initialized data. */
156	    .bss (NOLOAD) : ALIGN(4)
157	    {
158	        _sbss = ABSOLUTE(.);
159	        *(.bss .bss.*)
160	        *(.gnu.linkonce.b.*)
161	        *(COMMON)
162	        . = ALIGN(4);
163	        _ebss = ABSOLUTE(.);
164	    } > RAM
165	
166	    /* Heap: from end of BSS up to the MSP region.  N1 never uses it but
167	     * the symbols must exist for the common ARM code to link.
168	     */
169	    . = ALIGN(16);
170	    _sheap = ABSOLUTE(.);
171	    _eheap = ORIGIN(RAM) + LENGTH(RAM) - 4;
172	
173	    /* Stabs / debug sections -- discard nothing but keep them at VMA 0 so
174	     * they don't perturb the runtime image.
175	     */
176	    .stab              0 : { *(.stab) }
177	    .stabstr           0 : { *(.stabstr) }
178	    .stab.excl         0 : { *(.stab.excl) }
179	    .stab.exclstr      0 : { *(.stab.exclstr) }
180	    .stab.index        0 : { *(.stab.index) }
181	    .stab.indexstr     0 : { *(.stab.indexstr) }
182	    .comment           0 : { *(.comment) }
183	    .debug_abbrev      0 : { *(.debug_abbrev) }
184	    .debug_info        0 : { *(.debug_info) }
185	    .debug_line        0 : { *(.debug_line) }
186	    .debug_pubnames    0 : { *(.debug_pubnames) }
187	    .debug_aranges     0 : { *(.debug_aranges) }
188	}
