201	/****************************************************************************
202	 * Name: bk7258_irqinfo
203	 *
204	 * Description:
205	 *   Map a NuttX IRQ number to the (register, bit) pair that enables/disables
206	 *   it in the NVIC, honouring the enable/clear bank offset for external IRQs
207	 *   and the SYSHCON/SYSTICK control bits for the handful of manageable
208	 *   system exceptions.
209	 *
210	 ****************************************************************************/
211	
212	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
213	                          uintptr_t offset)
214	{
215	  int n;
216	
217	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
218	
219	  /* External device interrupt? */
220	
221	  if (irq >= BK7258_IRQ_FIRST)
222	    {
223	      n        = irq - BK7258_IRQ_FIRST;
224	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
225	      *bit     = (uint32_t)0x1 << (n & 0x1f);
226	    }
227	
228	  /* Processor exception -- only a few can be enabled/disabled. */
229	
230	  else
231	    {
232	      *regaddr = NVIC_SYSHCON;
233	      if (irq == NVIC_IRQ_MEMFAULT)
234	        {
235	          *bit = NVIC_SYSHCON_MEMFAULTENA;
236	        }
237	      else if (irq == NVIC_IRQ_BUSFAULT)
238	        {
239	          *bit = NVIC_SYSHCON_BUSFAULTENA;
240	        }
241	      else if (irq == NVIC_IRQ_USAGEFAULT)
242	        {
243	          *bit = NVIC_SYSHCON_USGFAULTENA;
244	        }
245	      else if (irq == NVIC_IRQ_SYSTICK)
246	        {
247	          *regaddr = NVIC_SYSTICK_CTRL;
248	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
249	        }
250	      else
251	        {
252	          return -EINVAL;  /* Invalid or unsupported exception */
253	        }
254	    }
255	
256	  return OK;
257	}
