60	/****************************************************************************
61	 * Name: bk7258_prioritize_syscall
62	 *
63	 * Description:
64	 *   Set the priority of the SVCall exception (system handler 11).  Needed
65	 *   internally even when CONFIG_ARCH_IRQPRIO is off.
66	 *
67	 ****************************************************************************/
68	
69	static inline void bk7258_prioritize_syscall(int priority)
70	{
71	  uint32_t regval;
72	
73	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
74	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
75	  regval |= (priority << NVIC_SYSH_PRIORITY_PR11_SHIFT);
76	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
77	}
