83	/****************************************************************************
84	 * Name: up_prioritize_irq
85	 *
86	 * Description:
87	 *   Set the priority of an IRQ.
88	 *
89	 ****************************************************************************/
90	
91	int up_prioritize_irq(int irq, int priority)
92	{
93	  uint32_t regaddr;
94	  uint32_t regval;
95	  int shift;
96	
97	  DEBUGASSERT(irq >= 0 && irq < NR_IRQS &&
98	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
99	
100	  if (irq < 16)
101	    {
102	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of the priority registers
103	       * (0-3 are invalid as raw indices; they are remapped internally).
104	       */
105	
106	      regaddr = NVIC_SYSH_PRIORITY(irq);
107	      irq    -= 4;
108	    }
109	  else
110	    {
111	      /* NVIC_IRQ_PRIORITY() maps {0..} to the external priority registers. */
112	
113	      irq    -= 16;
114	      regaddr = NVIC_IRQ_PRIORITY(irq);
115	    }
116	
117	  regval  = getreg32(regaddr);
118	  shift   = ((irq & 3) << 3);
119	  regval &= ~(0xff << shift);
120	  regval |= (priority << shift);
121	  putreg32(regval, regaddr);
122	
123	  return OK;
124	}
