126	/****************************************************************************
127	 * Name: up_irqinitialize
128	 *
129	 * Description:
130	 *   Bring the NVIC up to a known, ready state.  Called from up_initialize().
131	 *
132	 ****************************************************************************/
133	
134	void up_irqinitialize(void)
135	{
136	  uint32_t regaddr;
137	  int num_priority_registers;
138	  int i;
139	
140	  /* Step 1: Disable all 64 external NVIC lines.  BK7258_EXTERNAL_IRQS
141	   * is used for the loop bound; this clears banks starting at external
142	   * IRQ 0 and 32.
143	   */
144	
145	  for (i = 0; i < BK7258_EXTERNAL_IRQS; i += 32)
146	    {
147	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
148	    }
149	
150	  /* Step 2: Point VTOR at our flash-resident vector table (also set in
151	   * __start; redundant here but deterministic).
152	   */
153	
154	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
155	
156	  /* Step 3: Explicit barrier after the VTOR write. */
157	
158	  UP_DSB();
159	  UP_ISB();
160	
161	#ifdef CONFIG_ARCH_RAMVECTORS
162	
163	  /* Step 4: Copy all 80 entries from flash to RAM and switch VTOR to
164	   * g_ram_vectors.  arm_ramvec_initialize() does both.
165	   */
166	
167	  arm_ramvec_initialize();
168	
169	  /* Step 5: Repair the two boot-magic slots (64/65) that the bootloader
170	   * requires but that NuttX must route through exception_common.  These
171	   * are logical IRQ/vector slots 64 and 65.  Do not use ordinary
172	   * irq_attach() for this repair.
173	   */
174	
175	  {
176	    int ret0;
177	    int ret1;
178	
179	    ret0 = arm_ramvec_attach(BK7258_IRQ_ETHERNET, exception_common);
180	    ret1 = arm_ramvec_attach(BK7258_IRQ_SCALE0, exception_common);
181	
182	    /* Step 6: Capture/check both return values.  A failure must not
183	     * continue to final IRQ unmasking.  Both calls must be made before
184	     * the combined failure decision.
185	     */
186	
187	    if (ret0 < 0 || ret1 < 0)
188	      {
189	        PANIC();
190	      }
191	
192	    /* Step 7: Barrier after the two RAM slot writes. */
193	
194	    UP_DSB();
195	    UP_ISB();
196	
197	    /* Step 8: Debug assertions before unmasking. */
198	
199	    DEBUGASSERT(getreg32(NVIC_VECTAB) == (uint32_t)g_ram_vectors);
200	    DEBUGASSERT(g_ram_vectors[64] == ((uintptr_t)exception_common | 1u));
201	    DEBUGASSERT(g_ram_vectors[65] == ((uintptr_t)exception_common | 1u));
202	  }
203	
204	#endif /* CONFIG_ARCH_RAMVECTORS */
205	
206	  /* Step 9: Continue the existing default priorities, system-handler
207	   * attachments, IRQ stack coloring, and final up_irq_enable().
208	   */
209	
210	  /* Default-prioritise the system exceptions. */
211	
212	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
213	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
214	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
215	
216	  /* The NVIC ICTR register (bits 0-4) holds (number of IRQ lines / 32) - 1,
217	   * which also tells us how many priority registers to default-fill.
218	   */
219	
220	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
221	
222	  regaddr = NVIC_IRQ0_3_PRIORITY;
223	  while (num_priority_registers--)
224	    {
225	      putreg32(DEFPRIORITY32, regaddr);
226	      regaddr += 4;
227	    }
228	
229	  /* Attach the SVCall and HardFault handlers used by the scheduler. */
230	
231	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
232	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
233	
234	  /* PendSV runs at the lowest priority so it never preempts device IRQs. */
235	
236	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
237	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
238	
239	  /* Enable the MemManage fault if the MPU is in use. */
240	
241	#ifdef CONFIG_ARM_MPU
242	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
243	  up_enable_irq(NVIC_IRQ_MEMFAULT);
244	#endif
245	
246	#ifndef CONFIG_SUPPRESS_INTERRUPTS
247	
248	  /* Colour the interrupt stack (writes a sentinel pattern) and unmask IRQs. */
249	
250	  arm_color_intstack();
251	  up_irq_enable();
252	#endif
253	}
