260	/****************************************************************************
261	 * Name: bk7258_irqinfo
262	 *
263	 * Description:
264	 *   Map a NuttX IRQ number to the (register, bit) pair that enables/disables
265	 *   it in the NVIC, honouring the enable/clear bank offset for external IRQs
266	 *   and the SYSHCON/SYSTICK control bits for the handful of manageable
267	 *   system exceptions.
268	 *
269	 ****************************************************************************/
270	
271	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
272	                          uintptr_t offset)
273	{
274	  int n;
275	
276	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
277	
278	  /* External device interrupt? */
279	
280	  if (irq >= BK7258_IRQ_FIRST)
281	    {
282	      n        = irq - BK7258_IRQ_FIRST;
283	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
284	      *bit     = (uint32_t)0x1 << (n & 0x1f);
285	    }
286	
287	  /* Processor exception -- only a few can be enabled/disabled. */
288	
289	  else
290	    {
291	      *regaddr = NVIC_SYSHCON;
292	      if (irq == NVIC_IRQ_MEMFAULT)
293	        {
294	          *bit = NVIC_SYSHCON_MEMFAULTENA;
295	        }
296	      else if (irq == NVIC_IRQ_BUSFAULT)
297	        {
298	          *bit = NVIC_SYSHCON_BUSFAULTENA;
299	        }
300	      else if (irq == NVIC_IRQ_USAGEFAULT)
301	        {
302	          *bit = NVIC_SYSHCON_USGFAULTENA;
303	        }
304	      else if (irq == NVIC_IRQ_SYSTICK)
305	        {
306	          *regaddr = NVIC_SYSTICK_CTRL;
307	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
308	        }
309	      else
310	        {
311	          return -EINVAL;  /* Invalid or unsupported exception */
312	        }
313	    }
314	
315	  return OK;
316	}
