367	static void bk7258_uart_rxint(struct uart_dev_s *dev, bool enable)
368	{
369	  irqstate_t flags = enter_critical_section();
370	
371	  if (enable)
372	    {
373	      /* Three interrupt gates sit between the RX FIFO edge and the CPU and
374	       * all must be opened (in order) for the ISR to fire:
375	       *   1. peripheral-local: BK7258_UART1_INT_ENABLE bit1 (rx_need_read)
376	       *   2. on-chip int ctrl: BK7258_SYS_CPU0_INT_EN bit15 (UART1)
377	       *   3. Cortex-M33 NVIC:  up_enable_irq(BK7258_IRQ_UART1)
378	       * Only rx_fifo_need_read is armed: with the RX FIFO threshold set to
379	       * 1 in setup(), it fires on the first byte and de-asserts on drain,
380	       * so rx_finish (bit6) is redundant.  TX stays polled.
381	       */
382	
383	      BK7258_UART1_INT_ENABLE |= BK7258_UART_INT_RX_NEED_READ;
384	      BK7258_SYS_CPU0_INT_EN  |= BK7258_SYS_CPU0_INT_UART1;
385	      up_enable_irq(BK7258_IRQ_UART1);
386	
387	      /* Race-fix: drain any byte that pre-dated the gate opening. */
388	
389	      if (uart_rxavailable(dev))
390	        {
391	          uart_recvchars(dev);
392	        }
393	    }
394	  else
395	    {
396	      BK7258_UART1_INT_ENABLE &= ~BK7258_UART_INT_RX_NEED_READ;
397	      up_disable_irq(BK7258_IRQ_UART1);
398	    }
399	
400	  leave_critical_section(flags);
401	}
