745	
746	  if (timeout_ms == BEKEN_WAIT_FOREVER)
747	    {
748	      ret = file_mq_receive(&mq_adpt->mq, message,
749	                            mq_adpt->msgsize, 0);
750	      if (ret < 0)
751	        {
752	          wlerr("Failed to receive message from mqueue error=%d\n", ret);
753	        }
754	    }
755	  else
756	    {
757	      struct timespec timeout;
758	
759	      clock_gettime(CLOCK_REALTIME, &timeout);
760	      timeout.tv_sec  += timeout_ms / 1000;
761	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
762	
763	      if (timeout.tv_nsec >= 1000000000)
764	        {
765	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
766	          timeout.tv_nsec %= 1000000000;
767	        }
768	
769	      ret = file_mq_timedreceive(&mq_adpt->mq, message,
770	                                 mq_adpt->msgsize, 0, &timeout);
771	      if (ret < 0)
772	        {
773	          wlerr("Failed to timedreceive message from mqueue error=%d\n",
774	                ret);
775	        }
776	    }
777	
778	  return ret > 0 ? BK_OK : BK_FAIL;
779	}
