1007	      wlerr("ERROR: Failed to malloc struct timer_adpt\n");
1008	      return BK_FAIL;
1009	    }
1010	
1011	  memset(timer_apt, 0x0, sizeof(struct timer_adpt));
1012	  memset(timer, 0x0, sizeof(beken2_timer_t));
1013	
1014	  timer_apt->delay  = MSEC2TICK(time_ms);
1015	  timer_apt->priv   = timer;
1016	  timer_apt->repeat = false;
1017	
1018	  timer->handle   = timer_apt;
1019	  timer->function = function;
1020	  timer->left_arg = larg;
1021	  timer->right_arg = rarg;
1022	
1023	  return BK_OK;
1024	}
1025	
1026	bk_err_t rtos_start_oneshot_timer(beken2_timer_t *timer)
1027	{
1028	  int ret;
1029	  struct timer_adpt *timer_apt = (struct timer_adpt *)timer->handle;
1030	
1031	  ret = wd_start(&timer_apt->wdog, timer_apt->delay,
1032	                 os_timer_callback, (wdparm_t)timer_apt);
1033	  if (ret != OK)
1034	    {
1035	      wlerr("ERROR: Failed to start timer:%d\n", ret);
1036	    }
1037	
1038	  return beken_errno_trans(ret);
1039	}
1040	
1041	bk_err_t rtos_stop_oneshot_timer(beken2_timer_t *timer)
1042	{
1043	  int ret = OK;
1044	  struct timer_adpt *timer_apt;
1045	
1046	  if (timer && timer->handle)
1047	    {
1048	      timer_apt = (struct timer_adpt *)timer->handle;
1049	      if (WDOG_ISACTIVE(&timer_apt->wdog))
1050	        {
1051	          ret = wd_cancel(&timer_apt->wdog);
1052	          if (ret != OK)
1053	            {
1054	              wlerr("WARN: Failed to stop one-shot timer:%d\n", ret);
1055	            }
1056	        }
1057	    }
1058	
1059	  return BK_OK;
1060	}
