94	static isr_t* int_isr_del(icu_int_src_t src)
95	{
96	
97		LIST_HEADER_T *pos, *next;
98	
99		isr_t *cur_ptr;
100		isr_list_t *int_list;
101	
102		// icu_int_map_t icu_int_map_table[] = ICU_DEV_MAP;
103		if (src >= ARRAY_SIZE(icu_int_map_table)) {
104			ICU_LOGW("int_isr_del, int_src(%d) is out of icu_int_map_table range\r\n", src);
105			return NULL;
106		}
107		const icu_int_map_t *icu_int_map = &icu_int_map_table[src];
108	
109		uint32_t int_num = icu_int_map->int_bit;
110		uint32_t group_id = icu_int_map->group;
111	
112		int_list = &s_int_lists[group_id];
113	
114		ICU_LOGV("delete:src: %d pri=tem_ptr->pri, int_num = %d\r\n", src, int_num);
115		GLOBAL_INT_DECLARATION();
116	
117		GLOBAL_INT_DISABLE();
118		if (list_empty(&int_list->isr)) {
119			GLOBAL_INT_RESTORE();
120			return NULL;
121		}
122	
123		list_for_each_safe(pos, next, &int_list->isr) {
124			cur_ptr = list_entry(pos, isr_t, list);
125	
126			if (int_num == cur_ptr->int_num) {
127				ICU_LOGV("delete:src: %d pri=tem_ptr->pri, int_num = %d\r\n", src, int_num);
128				list_del(&cur_ptr->list);
129				GLOBAL_INT_RESTORE();
130				return cur_ptr;
131			}
132		}
133	
134		GLOBAL_INT_RESTORE();
135	
136		return NULL;
137	}
