188	bk_err_t bk_int_isr_register(icu_int_src_t src, int_group_isr_t isr, void*arg)
189	{
190		ICU_RETURN_ON_INVALID_DEVS(src);
191	
192		bk_int_isr_unregister(src);
193	
194		// icu_int_map_t icu_int_map_table[] = ICU_DEV_MAP;
195		if (src >= ARRAY_SIZE(icu_int_map_table)) {
196			ICU_LOGW("int_isr_register, int_src(%d) is out of icu_int_map_table range\r\n", src);
197			return BK_ERR_NOT_FOUND;
198		}
199		const icu_int_map_t *icu_int_map = &icu_int_map_table[src];
200	
201		uint8_t int_num = icu_int_map->int_bit;
202		uint8_t int_pri = icu_int_map->int_prio;
203		uint8_t group_id = icu_int_map->group;
204		isr_t *new_isr;
205	
206		ICU_LOGV("register isr: src=%d, num=%d, pri=%d, group=%d\r\n", src, int_num, int_pri, group_id );
207		new_isr = (isr_t*)os_malloc(sizeof(isr_t));
208		if(!new_isr) {
209			ICU_LOGE("cur_ptr malloc error\r\n");
210			return BK_ERR_NO_MEM;
211		}
212	
213		new_isr->isr_func = isr;
214		new_isr->int_num = int_num;
215		new_isr->pri = int_pri;
216	
217		return int_isr_add(new_isr, group_id);
218	}
