20	#define INT_NUMBER_MAX              (64)
21	#define TO_NVIC_IRQ(irq)            ((uint32_t)(irq))
22	
23	static __attribute__((section(".dtcm_sec_data"))) int_group_isr_t s_irq_handler[INT_NUMBER_MAX];
24	
25	void arch_int_enable_irq(uint32_t irq)
26	{
27		NVIC_EnableIRQ(TO_NVIC_IRQ(irq));
28	}
29	
30	void arch_int_disable_irq(uint32_t irq)
31	{
32		NVIC_DisableIRQ(TO_NVIC_IRQ(irq));
33	}
34	
35	uint32_t arch_int_get_enable_irq(uint32_t irq)
36	{
37		return NVIC_GetEnableIRQ(TO_NVIC_IRQ(irq));
38	}
39	
40	void arch_int_set_target_state(uint32_t irq)
41	{
42		NVIC_SetTargetState(TO_NVIC_IRQ(irq));
43	}
44	
45	void arch_int_clear_target_state(uint32_t irq)
46	{
47		NVIC_ClearTargetState(TO_NVIC_IRQ(irq));
48	}
49	
50	uint32_t arch_int_get_target_state(uint32_t irq)
51	{
52		return NVIC_GetTargetState(TO_NVIC_IRQ(irq));
53	}
54	
55	void arch_interrupt_set_priority(uint32_t int_number, uint32_t int_priority)
56	{
57		if (int_number > 0 && int_number < INT_NUMBER_MAX) {
58			NVIC_SetPriority(TO_NVIC_IRQ(int_number), int_priority);
59		}
60	
61		return;
62	}
63	
64	__IRAM_SEC void arch_int_set_default_priority(void)
65	{
66		/* group priority is depends on macro:__NVIC_PRIO_BITS.
67		   please refer to: www.freertos.org/zh-cn-cmn-s/RTOS-Cortex-M3-M4.html*/
68		NVIC_SetPriorityGrouping(PRI_GOURP_BITS_7_5);
69		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
70			NVIC_SetPriority(irq_type, IRQ_DEFAULT_PRIORITY);
71		}
72	}
73	
74	void arch_interrupt_register_int(uint32_t int_number, int_group_isr_t isr_callback)
75	{
76		if ((int_number > (INT_NUMBER_MAX - 1)) || isr_callback == NULL) {
77			return;
78		}
79	
80		s_irq_handler[int_number] = isr_callback;
81		NVIC_EnableIRQ(int_number);
82	}
83	
84	void arch_interrupt_unregister_int(uint32_t int_number)
85	{
86		if (int_number > (INT_NUMBER_MAX - 1)) {
87			return;
88		}
89		NVIC_DisableIRQ(int_number);
90		s_irq_handler[int_number] = NULL;
91	}
92	
93	__attribute__((section(".itcm_sec_code"))) int_group_isr_t arch_interrupt_get_handler(uint32_t int_number)
94	{
95		return s_irq_handler[int_number];
96	}
97	
98	void arch_int_init_all_irq(void)
99	{
100		__disable_irq();
101		__disable_fault_irq();
102	
103		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
104			NVIC_SetPriority(irq_type, IRQ_DEFAULT_PRIORITY);
105			NVIC_DisableIRQ(irq_type);
106		}
107	}
108	
109	void arch_int_enable_all_irq(void)
110	{
111		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
112			NVIC_SetPriority(irq_type, IRQ_DEFAULT_PRIORITY);
113			NVIC_EnableIRQ(irq_type);
114		}
115	
116		__enable_fault_irq();
117		__enable_irq();
118	}
119	
120	void arch_int_disable_all_irq(void)
121	{
122		__disable_irq();
123		__disable_fault_irq();
124	
125		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
126			NVIC_DisableIRQ(irq_type);
127		}
128	}
