   void bk7258_clear_pending_irq(int irq)
   {
     unsigned int external;

     DEBUGASSERT(irq >= BK7258_IRQ_FIRST && irq < NR_IRQS);

     if (irq < BK7258_IRQ_FIRST || irq >= NR_IRQS)
       {
         return;
       }

     external = (unsigned int)(irq - BK7258_IRQ_FIRST);
     putreg32(1u << (external & 0x1f),
              NVIC_IRQ_CLRPEND(external));
     UP_DSB();
     UP_ISB();
   }
   ```

   There is no generic NuttX `up_clear_pending_irq()` API, so the direct NVIC
   register operation is isolated in the chip’s existing NuttX NVIC glue rather
   than placed in the SDK bridge.

