114	int irq_attach(int irq, xcpt_t isr, FAR void *arg)
115	{
116	  int ret = OK;
117	#if NR_IRQS > 0
118	  int ndx = IRQ_TO_NDX(irq);
119	  if (ndx < 0)
120	    {
121	      ret = ndx;
122	    }
123	  else
124	    {
125	      /* If the new ISR is NULL, then the ISR is being detached.
126	       * In this case, disable the ISR and direct any interrupts
127	       * to the unexpected interrupt handler.
128	       */
129	
130	      irqstate_t flags = spin_lock_irqsave(&g_irqlock);
131	      if (isr == NULL)
132	        {
133	          /* Disable the interrupt if we can before detaching it.  We might
134	           * not be able to do this if:  (1) the device does not have a
135	           * centralized interrupt controller (so up_disable_irq() is not
136	           * supported). Or (2) if the device has different number for vector
137	           * numbers and IRQ numbers (in that case, we don't know the correct
138	           * IRQ number to use to disable the interrupt). In those cases, the
139	           * code will just need to be careful that it disables all interrupt
140	           * sources before detaching from the interrupt vector.
141	           */
142	
143	#if !defined(CONFIG_ARCH_NOINTC) && !defined(CONFIG_ARCH_VECNOTIRQ)
144	          up_disable_irq(irq);
145	#endif
146	          /* Detaching the ISR really means re-attaching it to the
147	           * unexpected exception handler.
148	           */
149	
150	          isr = irq_unexpected_isr;
151	          arg = NULL;
152	        }
153	
154	#ifdef CONFIG_IRQCHAIN
155	      /* Save the new ISR and its argument in the table.
156	       * If there is only one ISR on this irq, then .handler point to the ISR
157	       * and .arg point to the ISR parameter; Otherwise, .handler point to
158	       * irqchain_dispatch and .arg point to irqchain_s.
159	       */
160	
161	      if (is_irqchain(ndx, isr))
162	        {
163	          ret = irqchain_attach(ndx, isr, arg);
164	          spin_unlock_irqrestore(&g_irqlock, flags);
165	        }
166	      else
167	#endif
168	        {
169	          /* Save the new ISR and its argument in the table. */
170	
171	          g_irqvector[ndx].handler = isr;
172	          g_irqvector[ndx].arg     = arg;
173	    #ifdef CONFIG_SCHED_IRQMONITOR
