110	bk_err_t bk_int_isr_register(icu_int_src_t source,
111	                             int_group_isr_t handler, void *arg)
112	{
113	  unsigned int index = (unsigned int)source;
114	  int priority;
115	  int irq;
116	  int ret;
117	
118	  (void)arg; /* The CP CM33 SDK implementation also ignores this argument. */
119	
120	  irq = bk7258_sdk_source_to_irq(source);
121	  if (irq < 0)
122	    {
123	      return BK_ERR_INT_DEVICE_NONE;
124	    }
125	
126	  priority = bk7258_sdk_irq_encode_priority(
127	      BK7258_SDK_IRQ_DEFAULT_PRIORITY);
128	
129	  /* Registration replaces the previous owner of this source.  Keep the line
130	   * disabled and non-pending until both NuttX dispatch state and priority are
131	   * complete.
132	   */
133	
134	  up_disable_irq(irq);
135	  bk7258_clear_pending_irq(irq);
136	  g_bk7258_sdk_irq_handlers[index] = NULL;
137	
138	  ret = irq_detach(irq);
139	  if (ret < 0)
140	    {
141	      return BK_FAIL;
142	    }
143	
144	  ret = up_prioritize_irq(irq, priority);
145	  if (ret < 0)
146	    {
147	      return BK_FAIL;
148	    }
149	
150	  /* A NULL SDK callback has the same net effect as the vendor CM33 path:
151	   * the previous callback is removed and the interrupt stays disabled.
152	   */
153	
154	  if (handler == NULL)
155	    {
156	      return BK_OK;
157	    }
158	
159	  ret = irq_attach(irq, bk7258_sdk_irq_dispatch, NULL);
160	  if (ret < 0)
161	    {
162	      return BK_FAIL;
163	    }
164	
165	  g_bk7258_sdk_irq_handlers[index] = handler;
166	  UP_DSB();
167	  UP_ISB();
168	  up_enable_irq(irq);
169	
170	  return BK_OK;
171	}
