     flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
     result = up_prioritize_irq(irq, encoded) < 0 ? BK_FAIL : BK_OK;
     spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
     return result;
   }
